sqliteTable("sessions", {
  id: text("id").primaryKey(),
  runner: text("runner").notNull(),
  cwd: text("cwd").notNull(),
  nativeSessionId: text("native_session_id"),
  title: text("title").notNull(),
  createdAt: integer("created_at").notNull()
});
